CREATE TABLE planes(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,nombre VARCHAR(100) NOT NULL UNIQUE,descripcion VARCHAR(255),precio NUMERIC(10,2) NOT NULL CHECK(precio>0),duracion_dias INTEGER NOT NULL CHECK(duracion_dias BETWEEN 1 AND 366),activo BOOLEAN NOT NULL);
CREATE TABLE suscripciones(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,id_usuario BIGINT NOT NULL REFERENCES usuarios(id),id_plan BIGINT NOT NULL REFERENCES planes(id),nombre_plan VARCHAR(100) NOT NULL,estado VARCHAR(10) NOT NULL CHECK(estado IN ('ACTIVA','CANCELADA','VENCIDA')),fecha_inicio TIMESTAMPTZ NOT NULL,fecha_fin TIMESTAMPTZ NOT NULL,version BIGINT NOT NULL DEFAULT 0,CHECK(fecha_fin>fecha_inicio));
CREATE UNIQUE INDEX suscripcion_activa_por_plan ON suscripciones(id_usuario,id_plan) WHERE estado='ACTIVA';
CREATE TABLE suscripcion_periodos(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,id_suscripcion BIGINT NOT NULL REFERENCES suscripciones(id),id_usuario BIGINT NOT NULL REFERENCES usuarios(id),idempotency_key UUID NOT NULL,tipo VARCHAR(10) NOT NULL CHECK(tipo IN ('ALTA','RENOVACION')),fecha_inicio TIMESTAMPTZ NOT NULL,fecha_fin TIMESTAMPTZ NOT NULL,precio NUMERIC(10,2) NOT NULL CHECK(precio>0),UNIQUE(id_usuario,idempotency_key),CHECK(fecha_fin>fecha_inicio));
